@SuppressWarnings("unchecked")
void find_highest_score_path() {
    int[] ns = nextInts();
    int N = ns[0], M = ns[1];
    int[] A = nextInts();
    List<int[]>[] no = new List[200001];
    Arrays.setAll(no, i -> new ArrayList<>());

    for (int i = 0; i < M; i++) {
        int[] uv = nextInts();
        int u = uv[0] - 1, v = uv[1] - 1;
        if (A[u] < A[v]) no[A[u]].add(new int[] {u, v});
        if (A[u] > A[v]) no[A[v]].add(new int[] {v, u});
    }

    int[] dp = new int[N];
    Arrays.fill(dp, -1);
    dp[0] = 1;

    for (int i = 0; i < 200001; i++) {
        for (int[] uv : no[i]) {
            int u = uv[0], v = uv[1];
            if (dp[u] != -1) {
                dp[v] = Math.max(dp[v], dp[u] + 1);
            }
        }
    }

    System.out.println(dp[N - 1]);
}
